from ortools.linear_solver import pywraplp
import json

def solve_assignment_problem():
    cost_matrix = [
        [52, 89, 40, 77, 89, 14,  9, 77, 92, 77],
        [20, 17, 80, 96, 14, 43,  4, 69,  5, 29],
        [17, 34, 50, 77, 71, 31, 74, 26, 100, 20],
        [55, 63, 85, 35, 31, 46, 51, 70, 21, 24],
        [70, 13, 14, 26, 49, 80, 24, 48, 31, 42],
        [99, 72, 15, 91, 70, 94, 95, 50, 35, 30],
        [77, 83, 59, 20, 49, 97, 66, 21, 82, 42],
        [37, 78, 99, 75, 77,  2, 39, 53, 54, 90],
        [79,  6, 19, 90, 57, 16, 64, 15, 50,  2],
        [23, 75, 22, 81, 44, 22, 28, 67, 75, 81]
    ]

    num_employees = len(cost_matrix)
    num_tasks = len(cost_matrix[0])

    solver = pywraplp.Solver.CreateSolver('SCIP')
    if not solver:
        print("Failed to create solver")
        return

    x = {}
    for i in range(num_employees):
        for j in range(num_tasks):
            x[i, j] = solver.BoolVar(f'x[{i},{j}]')

    for i in range(num_employees):
        solver.Add(sum(x[i, j] for j in range(num_tasks)) == 1)

    for j in range(num_tasks):
        solver.Add(sum(x[i, j] for i in range(num_employees)) == 1)

    objective = solver.Sum(cost_matrix[i][j] * x[i, j] 
                          for i in range(num_employees) 
                          for j in range(num_tasks))
    solver.Minimize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        total_cost = int(solver.Objective().Value())

        assignment_list = [0] * num_employees
        for i in range(num_employees):
            for j in range(num_tasks):
                if x[i, j].solution_value() > 0.5:
                    assignment_list[i] = j

        print(json.dumps({
            "total_cost": total_cost,
            "employee_task_assignment": assignment_list
        }))
    else:
        print(f"No optimal solution found. Status: {status}")

if __name__ == "__main__":
    solve_assignment_problem()
